#pragma once
namespace native_wave_own_window_cases {
static std::string prepared(Fixture& f,std::string s){for(int n=0;n<8&&waiting(s,"transitionReady");++n)s=acknowledge(f,s);if(waiting(s,"frame"))s=f.command("tick","1000");return s;}
static std::string wave(const std::string& s,int id){auto begin=s.find("{\"id\":"+std::to_string(id)+",");check(begin!=std::string::npos,"ownwindow layer exists");size_t depth=0;bool quoted=false,escaped=false;size_t end=begin;for(;end<s.size();++end){char c=s[end];if(quoted){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='"')quoted=false;}else if(c=='"')quoted=true;else if(c=='{')++depth;else if(c=='}'&&!--depth){++end;break;}}auto l=s.substr(begin,end-begin);auto at=l.find("\"wave\":{");check(at!=std::string::npos,"ownwindow wave DTO exists");return l.substr(at);}
static std::string negative(Fixture& f){auto s=std::string(woh_command(f.handle,"action","start"));for(int i=0;i<8&&waiting(s,"transitionReady")&&s.find("\"error\":\"\"")!=std::string::npos;++i){auto tail=s.substr(s.find("\"transition\":"));auto p=std::to_string(uint64_t(number(tail,"id")));s=woh_command(f.handle,"transitionReady",p.c_str());}return s;}
static void run(){
    for(int preset:{43,44}){
        Program p;p.image(1000,"fake",0,{{180,0,930,1080,1,75}});p.alpha(0,128);p.wave(0,preset);p.commit();p.dialogue(0);p.clone(1,0,"fake");p.dialogue(1);p.push(0);p.op(0x241);p.dialogue(0);p.op(0xf4);
        Fixture f(std::move(p),true,"","fake 100 100\n");f.imageHeader("fake",1532,8130);f.command("textSpeed","0");auto s=prepared(f,f.command("action","start"));auto l=layerObject(s,0);
        check(waiting(s,"input")&&boolean(s,"canSave")&&number(wave(s,0),"preset")==preset,"large43/44 own-window prepares to normal saveable input");check(l.find("\"window\":{\"x\":180,\"y\":0,\"width\":930,\"height\":1080,\"colorMode\":1,\"softEdge\":75}")!=std::string::npos,"Native window raw fields remain present on waved owner");check(std::abs(number(l,"alpha")-128./255.)<1e-8,"Core keeps object opacity once rather than multiplying it into the wave source");
        woh_wave_clock(f.handle,1000);woh_wave_clock(f.handle,1250);s=woh_snapshot(f.handle);auto phase=number(wave(s,0),"elapsedMs");f.command("save","2");woh_destroy(f.handle);f.handle=woh_create(f.game.string().c_str());f.command("textSpeed","0");s=f.command("load","2");check(number(wave(s,0),"elapsedMs")==phase&&layerObject(s,0).find("\"softEdge\":75")!=std::string::npos,"unchanged WH20 layer/window and wave packet restores the own-window source");
        s=prepared(f,f.command("advance"));check(layerObject(s,1).find("\"softEdge\":75")!=std::string::npos&&layerObject(s,1).find("\"wave\":")==std::string::npos,"clone keeps its own window but never clones transient waveRT/clock");s=prepared(f,f.command("advance"));check(s.find("\"id\":0,")==std::string::npos&&layerObject(s,1).find("\"softEdge\":75")!=std::string::npos,"owner deletion frees its wave independently of regular cloned window");f.passed=true;
    }
    for(int kind=0;kind<4;++kind){Program p;p.image(1000,"fake",0,{{180,0,930,1080,1,75}});int preset=43;if(kind==0)preset=41;if(kind==1)p.blend(0,16,0);if(kind==2)p.image(1000,"fake",1,{},0);if(kind==3)p.noise(0,1);p.wave(0,preset);p.dialogue(0);p.op(0xf4);Fixture f(std::move(p),true);auto s=negative(f);check(s.find("\"error\":\"\"")==std::string::npos,"ownwindow extension keeps other preset/material/child/noise combinations strict");f.passed=true;}
}
}
